def two_pointers_opposite_ends(nums, target):
    """
    Template: Two pointers starting at opposite ends.
    Example: Find if pair exists that sums to target.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        current = nums[left] + nums[right]

        if current == target:
            return True  # Found the pair
        elif current < target:
            left += 1  # Need larger sum, move left pointer right
        else:
            right -= 1  # Need smaller sum, move right pointer left

    return False  # No pair found

def twoSum(nums, target):
    """Find if a pair in sorted array sums to target."""
    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            return True
        if current_sum < target:
            left += 1
        else:
            right -= 1

    return False

def threeSum(nums: List[int]) -> List[List[int]]:
    """Find all unique triplets that sum to zero."""
    nums.sort()
    result = []

    for i in range(len(nums) - 2):
        # Skip duplicate values for the first element
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left = i + 1
        right = len(nums) - 1

        while left < right:
            total = nums[i] + nums[left] + nums[right]

            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                result.append([nums[i], nums[left], nums[right]])

                # Skip duplicates for left and right pointers
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1

                left += 1
                right -= 1

    return result

def moveZeroes(nums):
    """
    Move all zeros to end while preserving non-zero element order in-place.
    """
    nextNonZero = 0
    for i in range(len(nums)):
        if nums[i] != 0:
            nums[nextNonZero], nums[i] = nums[i], nums[nextNonZero]
            nextNonZero += 1

def sortColors(nums):
    """Sort array of 0s, 1s, 2s in-place using Dutch National Flag."""
    left, right = 0, len(nums) - 1
    i = 0
    while i <= right:
        if nums[i] == 0:
            nums[i], nums[left] = nums[left], nums[i]
            left += 1
            i += 1
        elif nums[i] == 2:
            nums[i], nums[right] = nums[right], nums[i]
            right -= 1
        else:
            i += 1

def trapping_water(heights):
    """Calculate total rainwater trapped between elevation bars."""
    if not heights:
        return 0

    left, right = 0, len(heights) - 1
    left_max, right_max = heights[left], heights[right]
    water = 0

    while left < right:
        if left_max < right_max:
            left += 1
            if heights[left] >= left_max:
                left_max = heights[left]
            else:
                water += left_max - heights[left]
        else:
            right -= 1
            if heights[right] >= right_max:
                right_max = heights[right]
            else:
                water += right_max - heights[right]

    return water

def maxSum(nums, k):
    """Find max sum of distinct subarray of length k."""
    max_sum = float("-inf")
    start = 0
    state = {}
    curr_sum = 0

    for end in range(len(nums)):
        curr_sum = curr_sum + nums[end]
        state[nums[end]] = state.get(nums[end], 0) + 1

        if end - start + 1 == k:
            if len(state) == k:
                max_sum = max(max_sum, curr_sum)
            curr_sum = curr_sum - nums[start]
            state[nums[start]] = state[nums[start]] - 1
            if state[nums[start]] == 0:
                del state[nums[start]]
            start += 1

    return 0 if max_sum == float("-inf") else max_sum

def longestSubstringWithoutRepeat(s):
    """Return length of longest substring with all distinct characters."""
    state = {}
    start = 0
    max_length = 0

    for end in range(len(s)):
        if s[end] in state:
            start = max(start, state[s[end]] + 1)
        state[s[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start time
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]

    for current in intervals[1:]:
        prev = merged[-1]
        # Check overlap: current starts before prev ends
        if current[0] <= prev[1]:
            # Merge: extend prev end to max
            prev[1] = max(prev[1], current[1])
        else:
            # No overlap: add current as new interval
            merged.append(current)

    return merged

