def isValid(s):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            # Closing bracket
            if not stack or stack[-1] != mapping[char]:
                return False
            stack.pop()
        else:
            # Opening bracket
            stack.append(char)

    return len(stack) == 0

def isValid(s):
    """
    Determine if a string of brackets is valid.

    A string is valid if every opening bracket is closed by a matching
    type of bracket in the correct order.

    Args:
        s: String containing only '(', ')', '{', '}', '[', ']'

    Returns:
        True if the string is valid, False otherwise
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            if not stack or stack[-1] != mapping[char]:
                return False
            stack.pop()
        else:
            stack.append(char)

    return len(stack) == 0

