class Solution:
    def validateBST(self, root):
        """
        Validate if a binary tree is a valid BST.

        Args:
            root: TreeNode representing the root of the binary tree

        Returns:
            bool: True if the tree is a valid BST, False otherwise
        """
        def dfs(node, min_, max_):
            # base case: empty tree is valid
            if node is None:
                return True

            # check if current node's value is within valid range (exclusive)
            if node.val <= min_ or node.val >= max_:
                return False

            # recurse: left child must be < node.val, right child must be > node.val
            return dfs(node.left, min_, node.val) and dfs(node.right, node.val, max_)

        return dfs(root, float('-inf'), float('inf'))

