def build_adj_list(edges):
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)  # undirected
    return adj_list

def dfs(adjList):
    visited = set()
    def dfs_helper(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in adjList[node]:
            dfs_helper(neighbor)
    for node in adjList:
        if node not in visited:
            dfs_helper(node)

def dfs(matrix):
    visited = set()
    # up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs_helper(r, c):
        # check if already visited
        if (r, c) in visited:
            return
        # check if the cell is out of bounds
        if r < 0 or r >= len(matrix) or c < 0 or c >= len(matrix[0]):
            return

        visited.add((r, c))

        # explore all 4 neighbors
        for dr, dc in directions:
            dfs_helper(r + dr, c + dc)

    dfs_helper(0, 0)

def flood_fill(image, sr, sc, color):
    """
    Perform a flood fill on the image starting from pixel (sr, sc).

    Args:
        image: m x n grid of integers representing pixel colors
        sr: starting row index
        sc: starting column index
        color: new color to fill

    Returns:
        Modified image with flood fill applied
    """
    rows, cols = len(image), len(image[0])
    original_color = image[sr][sc]

    if original_color == color:
        return image

    def dfs(r, c):
        if image[r][c] == original_color:
            image[r][c] = color

            if r >= 1: dfs(r - 1, c)
            if r + 1 < rows: dfs(r + 1, c)
            if c >= 1: dfs(r, c - 1)
            if c + 1 < cols: dfs(r, c + 1)
        return

    dfs(sr, sc)
    return image

def numIslands(grid):
    """Count the number of islands in a binary grid.

    An island is a group of connected '1's (land) surrounded by '0's (water).
    Connections are only horizontal or vertical, not diagonal.

    Args:
        grid: List[List[str]] - Binary matrix where '1' is land and '0' is water

    Returns:
        int - Number of islands in the grid
    """
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    count = 0

    def dfs(r, c):
        grid[r][c] = 0
        if r + 1 < rows and grid[r + 1][c] == 1:
            dfs(r + 1, c)
        if r > 0 and grid[r - 1][c] == 1:
            dfs(r - 1, c)
        if c + 1 < cols and grid[r][c + 1] == 1:
            dfs(r, c + 1)
        if c > 0 and grid[r][c - 1] == 1:
            dfs(r, c - 1)
        return

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                count += 1
                dfs(i, j)

    return count

class Solution:
    def surrounded_regions(self, grid):
        """
        Modify grid in-place to replace surrounded 'O' regions with 'X'.
        Uses reverse approach: mark border-connected 'O's as safe via DFS.

        Args:
            grid: m x n matrix containing only 'X' and 'O'
        Returns:
            Modified grid with surrounded 'O's replaced by 'X'
        """
        if not grid:
            return grid

        rows = len(grid)
        cols = len(grid[0])

        def dfs(x, y):
            """Mark all 'O's reachable from border as 'S' (safe)."""
            # Out of bounds or not an 'O' - return
            if x < 0 or y < 0 or x >= rows or y >= cols or grid[x][y] != 'O':
                return

            # Mark as safe
            grid[x][y] = 'S'

            # Explore all 4 neighbors
            dfs(x + 1, y)
            dfs(x - 1, y)
            dfs(x, y + 1)
            dfs(x, y - 1)

        # Start DFS from first and last column
        for i in range(rows):
            if grid[i][0] == 'O':
                dfs(i, 0)
            if grid[i][cols - 1] == 'O':
                dfs(i, cols - 1)

        # Start DFS from first and last row
        for j in range(cols):
            if grid[0][j] == 'O':
                dfs(0, j)
            if grid[rows - 1][j] == 'O':
                dfs(rows - 1, j)

        # Final pass: flip unmarked 'O' to 'X', restore 'S' to 'O'
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 'O':
                    grid[i][j] = 'X'
                elif grid[i][j] == 'S':
                    grid[i][j] = 'O'

        return grid

class Solution:
    def pacific_atlantic_flow(self, grid):
        """Find all cells where water can flow to both Pacific and Atlantic oceans.

        Uses boundary DFS starting from ocean borders and flowing inland
        to neighbors with height >= current (reverse flow direction).

        Args:
            grid: m x n matrix of non-negative integers representing land heights

        Returns:
            List of [row, col] coordinates reachable from both oceans
        """
        if not grid or not grid[0]:
            return []

        rows, cols = len(grid), len(grid[0])
        pacific_reachable = set()
        atlantic_reachable = set()

        def dfs(r, c, reachable):
            reachable.add((r, c))
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in reachable and grid[nr][nc] >= grid[r][c]:
                        dfs(nr, nc, reachable)

        # DFS from Pacific borders (top row and left column)
        for r in range(rows):
            dfs(r, 0, pacific_reachable)
        for c in range(cols):
            dfs(0, c, pacific_reachable)

        # DFS from Atlantic borders (bottom row and right column)
        for r in range(rows):
            dfs(r, cols - 1, atlantic_reachable)
        for c in range(cols):
            dfs(rows - 1, c, atlantic_reachable)

        # Return intersection of both sets
        return list(pacific_reachable & atlantic_reachable)
